/* ============================================================================
   worddoc.js — branded Word response document (v0.13.0)

   Builds the Cloudstaff-branded .docx handed to the client at Finalise time,
   mimicking the "RFI Template Response" reference document:
     · A4, Arial 11pt body, Cloudstaff blue (#0079FF) headings
     · wordmark header + countries footer on page 1, round mark + page number
       and cloudstaff.com on subsequent pages
     · cover block, generic engagement-model introduction, the project's
       Q&As in workbook order, then the standard boilerplate sections
       (platforms, employment compliance, security, governance + transition
       plan, technology & AI, references)

   The client/organisation name is merged from the response project's name.
   Requires the `docx` IIFE global (loaded from CDN in index.html).
   Exposes: window.CS_WORD.buildResponseDocument(project, rows)  -> Document
            window.CS_WORD.buildResponseBlob(project, rows)      -> Promise<Blob>
   ========================================================================== */

(function (root) {
  "use strict";

  /* ---- brand constants ---------------------------------------------------- */
  var BLUE = "0079FF";
  var INK = "2C2E3C";
  var GREY = "6B6E7B";
  var LINE = "C9CDD6";
  var PAGE_W = 11900, PAGE_H = 16840;                 // A4, DXA
  var MARGIN = { top: 1440, right: 830, bottom: 1440, left: 1008, header: 567, footer: 400 };
  var CONTENT_W = PAGE_W - MARGIN.left - MARGIN.right; // 10062 DXA

  /* Cloudstaff wordmark (page-1 header) and round mark (later pages) */
  var LOGO_WORDMARK_B64 = "";
  var LOGO_MARK_B64 = "";

  function b64ToU8(b64) {
    if (typeof atob === "function") {
      var bin = atob(b64), u8 = new Uint8Array(bin.length);
      for (var i = 0; i < bin.length; i++) u8[i] = bin.charCodeAt(i);
      return u8;
    }
    return Uint8Array.from(Buffer.from(b64, "base64")); // Node (tests)
  }

  /* ---- tiny builders ------------------------------------------------------ */
  function D() { return root.docx; } // resolved lazily so load order can't bite

  // p("text") | p([{t:"plain "},{t:"bold",b:1}], {style,spacing,...})
  function p(content, opts) {
    var d = D(); opts = opts || {};
    var runs = (typeof content === "string" ? [{ t: content }] : content).map(function (r) {
      return new d.TextRun({
        text: r.t,
        bold: r.b ? true : undefined,        // never emit b=false — it overrides the style
        italics: r.i ? true : undefined,
        color: r.color || undefined, size: r.size || undefined
      });
    });
    return new d.Paragraph(Object.assign({ children: runs }, opts));
  }

  function linkLine(label, url) {
    var d = D();
    return new d.Paragraph({
      spacing: { after: 60 },
      children: [
        new d.TextRun({ text: label + "  —  ", bold: true }),
        new d.ExternalHyperlink({
          link: url,
          children: [new d.TextRun({ text: url, style: "Hyperlink" })]
        })
      ]
    });
  }

  function bullet(text) {
    return p(text, { numbering: { reference: "cs-bullets", level: 0 }, spacing: { after: 80 } });
  }
  function bulletLead(lead, rest) {
    return p([{ t: lead, b: 1 }, { t: rest }],
      { numbering: { reference: "cs-bullets", level: 0 }, spacing: { after: 80 } });
  }

  function answerParagraphs(text) {
    return String(text).split(/\r?\n+/).map(function (s) { return s.trim(); })
      .filter(Boolean).map(function (line) {
        return p(line, { spacing: { after: 140 } });
      });
  }

  function cell(content, width, opts) {
    var d = D(); opts = opts || {};
    return new d.TableCell({
      width: { size: width, type: d.WidthType.DXA },
      margins: { top: 80, bottom: 80, left: 100, right: 100 },
      shading: opts.fill ? { type: d.ShadingType.CLEAR, fill: opts.fill } : undefined,
      children: [p(opts.bold ? [{ t: content, b: 1 }] : content, { spacing: { after: 0 } })]
    });
  }

  /* ---- headers / footers --------------------------------------------------- */
  function makeHeaders() {
    var d = D();
    return {
      first: new d.Header({
        children: [new d.Paragraph({
          alignment: d.AlignmentType.RIGHT,
          spacing: { line: 240, lineRule: d.LineRuleType.AUTO, after: 0 },
          children: [new d.ImageRun({
            type: "png", data: b64ToU8(LOGO_WORDMARK_B64),
            transformation: { width: 200, height: 77 }
          })]
        })]
      }),
      default: new d.Header({
        children: [new d.Paragraph({
          spacing: { line: 240, lineRule: d.LineRuleType.AUTO, after: 0 },
          children: [new d.ImageRun({
            type: "png", data: b64ToU8(LOGO_MARK_B64),
            transformation: { width: 67, height: 67 }
          })]
        })]
      })
    };
  }

  function makeFooters() {
    var d = D();
    var tabRight = { type: d.TabStopType.RIGHT, position: CONTENT_W };
    return {
      first: new d.Footer({
        children: [new d.Paragraph({
          tabStops: [tabRight],
          children: [
            new d.TextRun({ text: "US   |   UK   |   AUSTRALIA   |   PHILIPPINES   |   INDIA", size: 16, color: GREY }),
            new d.TextRun({ text: "\tcloudstaff.com", size: 18, color: BLUE })
          ]
        })]
      }),
      default: new d.Footer({
        children: [new d.Paragraph({
          tabStops: [tabRight],
          children: [
            new d.TextRun({ children: [d.PageNumber.CURRENT], size: 16, color: GREY }),
            new d.TextRun({ text: "\tcloudstaff.com", size: 18, color: BLUE })
          ]
        })]
      })
    };
  }

  /* ---- transition-plan table ------------------------------------------------ */
  function transitionTable() {
    var d = D();
    var W = [2300, 4500, 3262]; // sums to CONTENT_W
    var rows = [
      ["Phase", "Activities", "Deliverables"],
      ["1. Planning & kick-off (Week 1)",
        "Confirm scope, roles, timelines, communication plan, success metrics and governance.",
        "Project plan, RACI, transition schedule"],
      ["2. Recruitment & onboarding (Weeks 1–4)",
        "Recruit staff, complete contracts, IT provisioning, security access, HR onboarding and compliance training.",
        "Fully onboarded team with required system access"],
      ["3. Knowledge transfer (Weeks 2–5)",
        "Process documentation review, shadowing sessions, SOP walkthroughs, SME training and Q&A sessions.",
        "Completed knowledge-transfer checklist, updated SOPs"],
      ["4. Parallel run (Weeks 4–6)",
        "New team performs work while the incumbent team continues to execute. Compare outputs, validate quality, identify gaps and refine processes.",
        "Performance reports, issue log, corrective actions"],
      ["5. Go-live / transition (Week 6+)",
        "New team assumes primary responsibility; incumbent team provides hypercare support.",
        "Successful handover, operational ownership transferred"],
      ["6. Stabilisation (2–4 weeks)",
        "Monitor KPIs, conduct regular governance meetings, resolve outstanding issues and optimise processes.",
        "Stable operations and continuous-improvement plan"]
    ];
    var border = { style: d.BorderStyle.SINGLE, size: 4, color: LINE };
    return new d.Table({
      width: { size: CONTENT_W, type: d.WidthType.DXA },
      columnWidths: W,
      borders: { top: border, bottom: border, left: border, right: border, insideHorizontal: border, insideVertical: border },
      rows: rows.map(function (r, i) {
        return new d.TableRow({
          tableHeader: i === 0,
          children: r.map(function (c, j) {
            return cell(c, W[j], i === 0 ? { bold: true, fill: "EAF3FF" } : (j === 0 ? { bold: true } : {}));
          })
        });
      })
    });
  }

  /* ---- boilerplate copy ------------------------------------------------------ */
  function introSection(client) {
    return [
      p("Introduction — our engagement model", { style: "CsIntroHeading" }),
      p("Cloudstaff was founded in 2011 by Australian technology entrepreneur Lloyd Ernst and has grown into one of the leading offshore workforce partners for Australian business, with more than 6,000 staff serving clients across 17 countries. The Australian Financial Review has recognised Cloudstaff as one of Australia's 100 fastest-growing companies. Our service lines span accounting and finance, back office and administration, customer service, creative and marketing, engineering and drafting, software development and technical support, delivered from Cloudstaff-operated centres in the Philippines with additional delivery locations in Colombia and India."),
      p([{ t: "What sets Cloudstaff apart is not capacity but " }, { t: "people who stay", b: 1 },
        { t: ". We have built the business around being an employer of choice — recognised year after year among the best companies to work for at the HR Asia Awards and through the Stevie Awards — and that investment shows up in the numbers that matter most to a long-term partner: staff retention with monthly resignation rates that have run below 1%. Behind those figures is a genuine employee proposition: great benefits, top offices, and an engagement and recognition program spanning Dreampoints rewards, BidHero auctions, Gems (capital event bonuses), mid-year team building and the year-end ROAR celebration." }]),
      p("Our “Two Families” culture lets a client invest alongside us in the team's recognition and experience, so " + client + "'s offshore team feels part of " + client + " rather than a faceless outsourced pool. The real prize is a stable, engaged team whose tenure protects your institutional knowledge and compounds in value across the life of the partnership."),
      p([{ t: "On the engagement model, we propose " }, { t: "dedicated Virtual Staffing", b: 1 },
        { t: ": fully employed Cloudstaff team members working as a direct extension of " + client + "'s team, on " + client + "'s hours and under " + client + "'s day-to-day direction. " + client + " defines and monitors the KPIs and owns process and operational quality; Cloudstaff owns the people platform around the team — recruitment, employment, HR and payroll, statutory compliance, secure facilities and technology, retention, and team-lead oversight — and provides the reporting and supervision that support " + client + "'s quality outcomes." }]),
      p([{ t: "See for yourself why Cloudstaff is a number-one employer in the Philippines:", b: 1 }], { spacing: { before: 120, after: 80 } }),
      linkLine("PERKS Boxes", "https://youtube.com/shorts/ZuWRA5oEIhQ"),
      linkLine("Office walk-throughs", "https://vimeo.com/cloudstaff/walkthrough"),
      linkLine("ROAR (Cloudstaff end-of-year party)", "https://youtu.be/gX1Uc1JHfJI"),
      linkLine("Our leadership team", "https://www.cloudstaff.com/why-cloudstaff/leadership-team/")
    ];
  }

  function platformsSection(client) {
    return [
      p("How we work — platforms and visibility", { style: "CsHeading1" }),
      p([{ t: "MyStaff", b: 1 }, { t: " by Cloudstaff is our workforce-management platform used by clients and managers to oversee their teams — visibility into attendance, productivity and communication, plus timesheets, leave, performance and service requests." }]),
      p("Our proprietary software platform includes:", { spacing: { after: 80 } }),
      bulletLead("Cloudstaff Jobs: ", "our candidate tracking and recruiting platform."),
      bulletLead("Workbench: ", "task tracking."),
      bulletLead("Buzz: ", "communications platform that works when you can't."),
      bulletLead("Tap: ", "mobile intranet with options to configure " + client + "-specific pages."),
      bulletLead("Vibe: ", "quickly provide input on your staff and service."),
      bulletLead("Cloudstaff Mobile: ", "quick features on the go, plus our virtual account managers if you need to raise something with us.")
    ];
  }

  function employmentSection(client) {
    return [
      p("Employment and statutory compliance", { style: "CsHeading1" }),
      p("Cloudstaff is the legal employer of every Cloudstaffer and is solely responsible for all HR, employment, payroll, discipline and dismissal matters. No employment relationship arises between " + client + " and any Cloudstaffer; " + client + " directs the day-to-day work within the assigned functions only. This is set out expressly in our Virtual Staffing Service Terms."),
      p("Cloudstaff administers payroll and all mandatory statutory employer and employee contributions in each delivery location as part of the Employee Direct Cost. For the Philippines this covers SSS, PhilHealth, Pag-IBIG and BIR withholding, administered to statutory deadlines with internal controls."),
      p("Official proof of statutory remittance — receipts, e-payment confirmations and agency records — can be provided on reasonable request, and remittance in full can be evidenced as a condition of continued engagement.")
    ];
  }

  function securitySection() {
    return [
      p("Data protection and security", { style: "CsHeading1" }),
      p("Cloudstaff protects information through a layered security framework aligned with ISO/IEC 27001 and independently audited under SOC 2 Type 2. Cloudstaff-managed PCs (mPC) are secured with BitLocker encryption, Endpoint Detection and Response (EDR), Next-Generation Antivirus (NGAV), identity threat detection and response, multi-factor authentication (MFA), role-based access controls, single sign-on where supported, restricted administrative privileges, unique local administrator passwords per device, automated patch management and continuous monitoring. Network security is provided through next-generation firewalls with intrusion prevention, DNS filtering, web filtering and application control, and facilities have biometric access control with 24/7 physical security."),
      p("Customer data is generally accessed, processed and stored within customer-managed systems, where authentication, access permissions, encryption, monitoring and data-protection controls are configured and managed by the customer. Access is granted on a least-privilege basis and logged — provisioned at onboarding and revoked promptly on any personnel change, with deprovisioning logged."),
      p("Cloudstaff supports reasonable client audit rights, subject to reasonable notice and scheduling. Independent assurance is available under NDA, including our SOC 2 (Type I and II) reports and ISO/IEC 27001 certification; Cloudstaff also holds ISO 9001 and aligns with GDPR and HIPAA requirements where relevant, with a PCI DSS-aligned payment-handling environment."),
      p("Cloudstaff maintains a formal incident-response process aligned with ISO 27001 and SOC 2, and will notify the client within 72 hours of becoming aware of an actual or suspected security incident affecting Cloudstaff-managed systems, devices, networks or services that could reasonably impact client systems or information — including the nature of the incident, affected systems, potential impact, containment actions and remediation activities."),
      p("Cloudstaff does not subcontract services involving customer data without customer approval. Sub-processors, where used, are bound by confidentiality and data-protection obligations at least as protective as those we accept.")
    ];
  }

  function governanceSection(client) {
    return [
      p("Governance and working model", { style: "CsHeading1" }),
      p(client + " is supported by an account-management structure — on-demand digital enquiries via the Cloudstaff mobile app and virtual account-management team, an assigned Account Manager as your main operational point of contact, and an Australian-based BDM for commercial conversations, escalations and quarterly planning. We maintain a regular reporting rhythm through the MyStaff and Workbench platforms and a clear three-tier escalation path: operational matters via the account manager, employment matters via Cloudstaff HR, and anything beyond that to the local BDM or regional leader as required."),
      p("Cloudstaff minimises operational risk through structured governance, documented processes and cross-functional knowledge sharing to avoid single points of failure across service delivery. Our approach includes:", { spacing: { after: 80 } }),
      bulletLead("Cross-training and knowledge transfer: ", "critical business processes are documented and shared across designated team members to ensure continuity during planned or unplanned absences."),
      bulletLead("Succession and backup planning: ", "key roles have identified backup resources with appropriate training and system access."),
      bulletLead("Comprehensive documentation: ", "SOPs, work instructions, process maps and knowledge articles are maintained in central repositories and regularly reviewed."),
      bulletLead("Capability register: ", "an up-to-date matrix of each team member's skills, certifications, competencies, training status and cross-skilling coverage."),
      bulletLead("Access register: ", "a controlled record of all system and application access, assigned roles, approval records and review dates, provisioned on least privilege and periodically audited."),
      bulletLead("Regular governance reviews: ", "capability and access registers are reviewed in operational governance meetings to remain current and compliant."),
      bulletLead("Business continuity: ", "these practices form part of Cloudstaff's broader business-continuity and operational-resilience framework, with provision for office, alternate-site and work-from-home failover."),
      p("We propose a phased transition — planning and alignment (KPIs, access, controls), onboarding (recruitment, IT provisioning, security and compliance training) and a client-led knowledge transfer:", { spacing: { before: 120, after: 120 } }),
      transitionTable(),
      p("", { spacing: { after: 0 } })
    ];
  }

  function technologySection() {
    return [
      p("Technology and AI capability", { style: "CsHeading1" }),
      p("Cloudstaff operates at the intersection of people and technology. Our operations run on proprietary platforms — MyStaff and Workbench — alongside Microsoft 365 for communications and collaboration, an enterprise security and monitoring stack, and ticketing and knowledge-management tooling, integrated to provide auditable, digital workflows. Core capabilities include Microsoft Entra ID for identity and access management, Microsoft Intune for endpoint management, remote monitoring and management (RMM), EDR, identity threat detection and response, and next-generation firewalls."),
      p("Cloudstaff provides controlled access to enterprise AI through AllChat, Cloudstaff's internally governed AI platform providing secure access to approved commercial large language models (Gemini, Anthropic, OpenAI, Grok). Data uploaded by staff is protected in a secure Azure cloud and tokenised before being passed to the foundational LLM of choice, protecting client data from being added to LLM learning systems. External and public AI platforms are blocked by default unless specifically approved, and AI use is governed and logged under our AI policy. Team members are prohibited from entering customer confidential information, source code, credentials or sensitive data into AI systems unless explicitly authorised by the customer. Agentic AI capabilities that perform autonomous actions or connect to external systems are not enabled by default and require separate review and approval."),
      p("Cloudstaff also uses AI within its own recruitment: with a database of more than 1,000,000 candidates, AI powers resume extraction and databasing for skills and experience matching, AI-assisted shortlisting for recruiters to human-vet, and applicant matching and prioritisation. All Cloudstaffers can access AI training and certification through the Cloudstaff Academy.")
    ];
  }

  function referencesSection() {
    return [
      p("Client references", { style: "CsHeading1" }),
      p([{ t: "Cloudstaff has an extensive base of Australian clients and we are happy to provide named references and arrange reference calls, " },
      { t: "subject to each client's confidentiality consent.", i: 1 }]),
      linkLine("Public testimonial — Wipfli (Accounting)", "https://youtu.be/4SH-C90DIk0")
    ];
  }

  /* ---- document assembly ------------------------------------------------------ */
  function buildResponseDocument(project, rows) {
    var d = D();
    if (!d) throw new Error("The Word library hasn't loaded — check your connection and reload.");
    var client = (project && project.name || "").trim() || "your organisation";
    var prepared = new Date().toLocaleDateString("en-AU", { day: "numeric", month: "long", year: "numeric" });

    var qas = (rows || []).slice().sort(function (a, b) { return (a.seq || 0) - (b.seq || 0); });
    var qaChildren = [
      p("Our response to your questions", { style: "CsHeading1", pageBreakBefore: true }),
      p("The sections below reproduce each question from " + client + "'s request together with Cloudstaff's response. The same answers are written into the completed response workbook that accompanies this document.")
    ];
    qas.forEach(function (r) {
      qaChildren.push(p(String(r.question || ""), { style: "CsQuestion" }));
      qaChildren.push.apply(qaChildren, answerParagraphs(r.answer || ""));
    });

    var children = [
      p("Cloudstaff — Response to Request for Proposal / Information", { style: "CsTitle" }),
      p(client, { style: "CsCoverClient" }),
      p([{ t: "Reference: " + (project && project.file_name || "response project") + "   ·   Prepared " + prepared, color: GREY, size: 20 }],
        { spacing: { after: 480 }, border: { bottom: { style: d.BorderStyle.SINGLE, size: 6, color: LINE, space: 6 } } })
    ]
      .concat(introSection(client))
      .concat(qaChildren)
      .concat(platformsSection(client))
      .concat(employmentSection(client))
      .concat(securitySection())
      .concat(governanceSection(client))
      .concat(technologySection())
      .concat(referencesSection());

    return new d.Document({
      creator: "Cloudstaff RFP Builder",
      title: "Cloudstaff response — " + client,
      styles: {
        default: {
          document: { run: { font: "Arial", size: 22, color: INK } }
        },
        paragraphStyles: [
          {
            id: "Normal", name: "Normal", quickFormat: true,
            run: { font: "Arial", size: 22, color: INK },
            paragraph: { spacing: { after: 160, line: 276, lineRule: d.LineRuleType.AUTO } }
          },
          {
            id: "CsTitle", name: "CS Title", basedOn: "Normal", next: "Normal",
            run: { bold: true, size: 32 },
            paragraph: { spacing: { after: 60 } }
          },
          {
            id: "CsCoverClient", name: "CS Cover Client", basedOn: "Normal", next: "Normal",
            run: { size: 24, color: BLUE, bold: true },
            paragraph: { spacing: { after: 60 } }
          },
          {
            id: "CsIntroHeading", name: "CS Intro Heading", basedOn: "Normal", next: "Normal",
            run: { bold: true, size: 36, color: BLUE },
            paragraph: { spacing: { before: 240, after: 200 }, outlineLevel: 0, keepNext: true }
          },
          {
            id: "CsHeading1", name: "CS Heading 1", basedOn: "Normal", next: "Normal",
            run: { bold: true, size: 30, color: BLUE },
            paragraph: { spacing: { before: 480, after: 160 }, outlineLevel: 0, keepNext: true }
          },
          {
            id: "CsQuestion", name: "CS Question", basedOn: "Normal", next: "Normal",
            run: { bold: true },
            paragraph: { spacing: { before: 280, after: 100 }, keepNext: true }
          }
        ],
        characterStyles: [
          { id: "Hyperlink", name: "Hyperlink", run: { color: BLUE, underline: {} } }
        ]
      },
      numbering: {
        config: [{
          reference: "cs-bullets",
          levels: [{
            level: 0, format: d.LevelFormat.BULLET, text: "•",
            alignment: d.AlignmentType.LEFT,
            style: { paragraph: { indent: { left: 420, hanging: 220 } } }
          }]
        }]
      },
      sections: [{
        properties: {
          page: { size: { width: PAGE_W, height: PAGE_H }, margin: MARGIN },
          titlePage: true
        },
        headers: makeHeaders(),
        footers: makeFooters(),
        children: children
      }]
    });
  }

  function buildResponseBlob(project, rows) {
    var d = D();
    return d.Packer.toBlob(buildResponseDocument(project, rows));
  }

  root.CS_WORD = {
    buildResponseDocument: buildResponseDocument,
    buildResponseBlob: buildResponseBlob
  };
})(typeof window !== "undefined" ? window : globalThis);
